starter:
def reset(items):
    """Empty the caller's list, in place."""
    items = []

solution:
def reset(items):
    """Empty the caller's list, in place."""
    items.clear()

def collect(item, into=None):
    """Return a list containing `item`, or append it to `into` if one is given."""
    if into is None:
        into = []
    into.append(item)
    return into

