    return a is b

solution:
def same_value(a, b):
    """Return True if a and b have the same value."""
    return a == b

starter:
def shout(text: str) -> str:
    """Return text in upper case with an exclamation mark on the end."""
    text.append("!")
    return text.upper()


print(shout("hello"))

solution:
def shout(text: str) -> str:
    """Return text in upper case with an exclamation mark on the end."""
    return (text + "!").upper()


print(shout("hello"))

starter:
def duplicate(grid):
    """Return a fully independent copy of a list of rows."""
    return list(grid)

solution:
def duplicate(grid):
    """Return a fully independent copy of a list of rows."""
    out = []
    for row in grid:
        out.append(list(row))
    return out

